def run_map_sum_ops(ops):
    root = {'children': {}, 'score': 0}
    values = {}

    def insert(key, val):
        delta = val - values.get(key, 0)
        values[key] = val
        node = root
        node['score'] += delta
        for ch in key:
            if ch not in node['children']:
                node['children'][ch] = {'children': {}, 'score': 0}
            node = node['children'][ch]
            node['score'] += delta

    def prefix_sum(prefix):
        node = root
        for ch in prefix:
            if ch not in node['children']:
                return 0
            node = node['children'][ch]
        return node['score']

    output = []
    for op in ops:
        name = op[0]
        if name == 'insert':
            insert(op[1], op[2])
        elif name == 'sum':
            output.append(prefix_sum(op[1]))
    return output

